// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    Reverter recp;

    function setUp() public { c = new W_WALLET(address(new Log())); recp = new Reverter(); }

    // fuzz params: amount to put/collect, and an unlockTime offset
    function testFuzz_property(uint128 fuzzAmt, uint256 unlockOffset) public {
        // Keep amounts reasonable and non-zero, and ensure fuzzAmt >= MinSum so Collect precondition can hold
        uint256 amt = bound(uint256(fuzzAmt), 1 ether, 100 ether);
        // pick an unlocking time strictly in the past so we can control block.timestamp vs unlockTime
        uint256 unlockTime = block.timestamp + (unlockOffset % 10) + 1; // small future offset

        // Fund the recipient EOA and the contract caller (we'll use address(this) as actor via prank)
        vm.deal(address(this), amt * 2);

        // First: Put into contract from address(this) so Acc[address(this)].balance = amt
        vm.prank(address(this));
        c.Put{value: amt}(unlockTime);

        // Now ensure the account balance in contract is at least MinSum and >= amt
        (uint256 uTime, uint256 bal) = c.Acc(address(this));
        // sanity: should have stored the balance
        assertTrue(bal >= amt);

        // Move time forward past unlockTime so Collect preconditions on time pass
        vm.warp(unlockTime + 1);

        // Now we want to test behavior when msg.sender (the refund recipient) REVERTS on receive.
        // The contract calls msg.sender.call{value:_am}(""); so we must make msg.sender be a contract that reverts on receive.
        // We'll call Collect while prank-sending as the Reverter contract: i.e., set msg.sender to recp.

        // Transfer some ether to the contract to ensure it has funds to pay out (though it should use its own held balance)
        // Not strictly necessary, but keep it funded
        vm.deal(address(c), amt);

        // Now perform Collect as if called by the reverter contract. We need Acc[recp] to have sufficient balance and unlockTime
        // So first put funds into Acc[recp] by having recp call Put. But recp is a contract; we can instruct it to call c.Put via its helper method.
        // Give recp some ETH to perform Put
        vm.deal(address(recp), amt);
        // recp will call c.Put(unlockTime) and thereby populate Acc[recp]
        recp.callPut(address(c), unlockTime, amt);

        // Sanity check: Acc[recp].balance >= amt and unlockTime set
        (uint256 ru, uint256 rbal) = c.Acc(address(recp));
        assertTrue(rbal >= amt);

        // Advance time past unlockTime so Collect can proceed
        vm.warp(unlockTime + 2);

        // Now have recp call Collect on c. Because recp.revertOnReceive is true, its receive() will revert when c tries to send
        // We must call Collect from recp, so instruct recp to call c.Collect. recp will perform the external call and we capture whether it completed.

        bool ok = recp.callCollect(address(c), amt);

        // GENERAL RULE (one assertion): For the reference contract, when the recipient (msg.sender) reverts on receive, Collect must NOT complete successfully — it must revert, so ok == false.
        // The mutant that ignores the failed call will return ok == true for some inputs (i.e., will complete and deduct balance). We therefore assert ok == false.
        assertTrue(!ok);
    }
}

// Helper contract that reverts on receive and can invoke Put/Collect on C on its own behalf
contract Reverter {
    bool public shouldRevert = true;

    // Call c.Put from this contract, sending value
    function callPut(address caddr, uint256 unlockTime, uint256 value) external {
        W_WALLET(payable(caddr)).Put{value: value}(unlockTime);
    }

    // Call c.Collect from this contract; return true if call completed, false if it reverted
    function callCollect(address caddr, uint256 am) external returns (bool) {
        try W_WALLET(payable(caddr)).Collect{value:0}(am) {
            return true;
        } catch {
            return false;
        }
    }

    // Revert on receive to simulate failing payout
    receive() external payable {
        revert("revert receive");
    }
}
